"""
	survival_score = 80% * survival time score + 20% * win place score

	: type timeSurvived: int -- participant time survived
	: type duration: int  -- match duration time
	: type winPlace: int
	: rtype survival_score: int
	"""
def survival_score(timeSurvived: Any, duration: Any, winPlace: Any) -> object {
    survival = (timeSurvived / duration) * 100;
    if (winPlace == 1) {
        win_place = 100;
    } else {
        win_place = 100 - winPlace;
    }
    survival_score = int(((survival * 0.8) + (win_place * 0.2)));
    if (survival_score < 50) {
        survival_score = 50;
    }
    return survival_score;
}

"""Theoretical model for the low-pass filtering by the PSD.

    See ref. 2, Eq. (11).
    """
def g_diode(f: Any, f_diode: Any, alpha: Any) -> object {
    return ((alpha ** 2) + ((1 - (alpha ** 2)) / (1 + ((f / f_diode) ** 2))));
}

